import { Component, EventEmitter, Input, Output } from '@angular/core';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-confirm-dialog',
  standalone: true,
  imports: [CommonModule],
  templateUrl: './confirm-dialog.component.html',
  styleUrls: ['./confirm-dialog.component.scss']
})
export class ConfirmDialogComponent {
  @Input() open = false;
  @Input() title = 'Confirm';
  @Input() message = 'Are you sure?';
  @Output() closed = new EventEmitter<boolean>();
}
<div class="backdrop" *ngIf="open" role="dialog" aria-modal="true" aria-label="{{title}}">
  <div class="dialog card">
    <h3>{{ title }}</h3>
    <p>{{ message }}</p>
    <div class="actions">
      <button class="btn btn-danger" (click)="closed.emit(true)">Delete</button>
      <button class="btn btn-secondary" (click)="closed.emit(false)">Cancel</button>
    </div>
  </div>
</div>
